package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Nơi ẩn náu từ một người hàng xóm xấu", "Ôi Allah, tôi cầu xin Ngài che chở khỏi một người hàng xóm xấu ở nơi thường trú, để người hàng xóm tiếp tục cuộc hành trình.", "Để bảo vệ khỏi một người hàng xóm xấu.", "Nhà tiên tri ﷺ đã ra lệnh tìm nơi ẩn náu khỏi điều này."),
        "dua_ishfi_abdak" to DuaText("Để phục hồi một người bệnh", "Lạy Allah, xin hãy chữa lành cho tôi tớ của Ngài để anh ta có thể đối đầu với kẻ thù vì Ngài hoặc bước đến cầu nguyện cho Ngài.", "Đối với người bệnh khi đến thăm ông.", "Nhà tiên tri ﷺ đã dạy nói điều này cho người bệnh."),
        "dua_la_mania" to DuaText("Không ai có thể giữ lại những gì bạn cho đi", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự ca ngợi, và Ngài có quyền trên mọi sự. Lạy Allah, không ai có thể từ chối những gì Ngài ban và không ai có thể cho những gì Ngài giữ lại và của cải của người giàu không có tác dụng gì chống lại Ngài.", "Sau lễ cầu nguyện bắt buộc.", "Nhà tiên tri ﷺ đã nói điều này sau mỗi lời cầu nguyện bắt buộc."),
        "dua_slaughtering" to DuaText("Khi giết mổ động vật", "Nhân danh Allah và Allah là Đấng vĩ đại nhất.", "Khi hiến tế hoặc giết mổ một con vật.", "Nhà tiên tri ﷺ đã nói Bismillah và takbir tại thời điểm hiến tế."),
        "dua_undressing" to DuaText("Khi Cởi Quần Áo", "Nhân danh Allah.", "Khi cởi quần áo (để thay quần áo hoặc thay quần áo).", "Nó trở thành một tấm bình phong che chắn đôi mắt của jinn và những bộ phận riêng tư của một người."),
        "dua_ilbas_jadidan" to DuaText("Nhìn thấy ai đó trong bộ quần áo mới", "Mặc mới, sống đáng khen và chết như một vị tử đạo.", "Khi nhìn thấy một anh em Hồi giáo trong bộ quần áo mới.", "Nhà tiên tri ﷺ đã thực hiện điều này khi nhìn thấy Umar (RA) trong bộ quần áo mới."),
        "dua_hajj_la_riya" to DuaText("Một Hajj không cần phô trương", "Ôi Allah, hãy biến nó thành một Hajj không phô trương và không tìm kiếm danh vọng.", "Vì sự chân thành khi thực hiện ý định Hajj.", "Nhà tiên tri ﷺ đã thực hiện điều này vào thời điểm diễn ra Hajj."),
        "dua_q_muslimayni_laka" to DuaText("Dua of Ibrahim & Ismail (AS) — Hãy khiến chúng tôi phục tùng", "Lạy Chúa, xin làm cho chúng con vâng phục Ngài và từ dòng dõi chúng con trở thành một dân tộc vâng phục Ngài. Xin chỉ cho chúng con nghi thức thờ phượng và nhận lấy sự ăn năn của chúng con. Quả thật, Ngài là Đấng Chấp nhận sự ăn năn, Đấng Thương Xót.", "Một sự phục tùng cho bản thân và con cháu của mình.", "Dua được tạo ra khi xây dựng Ka'bah."),
        "dua_q_iftah_baynana" to DuaText("Dua of Shu'aib (AS) — Người phán xét giữa chúng ta", "Lạy Chúa chúng con, xin hãy xét xử giữa chúng con và dân tộc chúng con một cách chân thật, và Ngài là thẩm phán tốt nhất.", "Để phán xét giữa sự thật và sự giả dối.", "Dua của Shu'ayb (AS) khi người dân của anh từ chối anh."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua of Musa (AS) — Không bao giờ là người giúp đỡ tội phạm", "Lạy Chúa, vì ơn Chúa đã ban cho con, con sẽ không bao giờ là kẻ giúp đỡ bọn tội phạm.", "Biết ơn những phước lành của Allah và cam kết không giúp đỡ những người làm sai.", "Lời cam kết của Musa (AS) sau khi ăn năn."),
        "dua_q_nuh_unsurni" to DuaText("Dua of Nuh (AS) — Giúp tôi với, họ từ chối tôi", "Lạy Chúa, xin giúp con vì họ đã từ chối con.", "Khi mọi người phủ nhận bạn và từ chối sự thật.", "Dua của Nuh (AS), đã được trả lời."),
        "dua_q_ihkum_bil_haqq" to DuaText("Lạy Chúa, Ngài phán xét bằng sự thật", "Lạy Chúa, xin hãy phán xét bằng sự thật. Và Chúa của chúng ta là Đấng Nhân từ nhất, người đang tìm kiếm sự trợ giúp chống lại những gì bạn mô tả.", "Trước những lời dối trá và cáo buộc sai trái.", "A dua đã dạy cho Nhà tiên tri ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Nương Nương Để Tránh Nợ Nợ Và Kẻ Thù", "Lạy Allah, con cầu xin Ngài che chở để khỏi bị nợ nần chồng chất, khỏi bị kẻ thù chế ngự và khỏi sự hả hê của kẻ thù.", "Bảo vệ khỏi gánh nặng nợ nần và sự thống trị của kẻ thù.", "Nhà tiên tri ﷺ đã từng tìm nơi ẩn náu khỏi những điều này."),
        "dua_faqr_qillah_dhillah" to DuaText("Nơi ẩn náu khỏi nghèo đói và tủi nhục", "Lạy Allah, con cầu xin Ngài che chở khỏi nghèo đói, thiếu thốn và tủi nhục cũng như khỏi đối xử sai trái với người khác hoặc bị đối xử sai trái.", "Để được an toàn khỏi khó khăn, thiếu thốn và tủi nhục.", "Nơi ẩn náu được Nhà tiên tri giảng dạy ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Tha thứ, thương xót, hướng dẫn, chữa lành, chu cấp", "Ôi Allah, hãy tha thứ cho tôi, thương xót tôi, hướng dẫn tôi, ban cho tôi hạnh phúc và chu cấp cho tôi.", "Nhà tiên tri ﷺ đã dạy dua này cùng với lời cầu nguyện cho những người Hồi giáo mới.", "Nhà tiên tri ﷺ đã nói: những lời này tập hợp cho bạn ở thế giới này và Đời sau."),
        "dua_ruku_laka_raka_tu" to DuaText("Trong Ruku - Tôi cúi đầu chào bạn", "Ôi Allah, tôi đã cúi đầu trước Ngài, tôi đã tin tưởng vào Ngài và tôi đã phục tùng Ngài. Thính giác, thị giác, tâm trí, xương và gân của tôi đều khiêm nhường trước mặt Ngài.", "Trong ruku (đặc biệt là trong những lời cầu nguyện tự nguyện).", "Nhà tiên tri ﷺ đã đọc điều này trong ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("In Sujood — Anh đã lạy em", "Ôi Allah, tôi đã phủ phục Ngài, tôi đã tin tưởng vào Ngài và tôi đã quy phục Ngài. Khuôn mặt của tôi đã phủ phục trước Đấng đã tạo ra nó, tạo hình nó và tạo ra thính giác và thị giác cho nó. Phúc thay Allah, đấng sáng tạo tốt nhất.", "Trong sujood (đặc biệt là trong những lời cầu nguyện tự nguyện).", "Nhà tiên tri ﷺ đã đọc điều này một cách vui vẻ."),
        "dua_ruku_sujood_subhanaka" to DuaText("Vinh danh Chúa, Chúa của chúng ta - Hãy tha thứ cho tôi", "Lạy Allah, Chúa của chúng tôi, xin vinh danh Ngài và ca ngợi Ngài. Ôi Allah, hãy tha thứ cho tôi.", "Trong ruku và sujood.", "Aisha (RA): Nhà tiên tri ﷺ thường nói điều này trong ruku và sujood."),
        "dua_q_musa_li_akhi" to DuaText("Dua of Musa (AS) — Hãy tha thứ cho tôi và anh trai tôi", "Lạy Chúa, xin tha thứ cho con và anh em con và nhận chúng con vào trong lòng thương xót của Ngài, vì Ngài là Đấng Nhân từ nhất trong những người hay thương xót.", "Tha thứ cho bản thân và anh em hoặc những người thân yêu của mình.", "Bản dua của Musa (AS) dành cho Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Tôi giao phó công việc của tôi cho Allah", "Và tôi giao phó công việc của mình cho Allah. Quả thật, Allah Hằng nhìn thấy mọi bề tôi của Ngài.", "Khi mọi người phản đối bạn và vấn đề phải được giao cho Allah.", "Lời của người có đức tin từ dân tộc Pharaoh; Allah sau đó đã bảo vệ anh ta khỏi những âm mưu xấu xa của họ."),
        "dua_q_hawariyyun" to DuaText("Dua của các môn đệ — Ghi lại chúng tôi với các nhân chứng", "Lạy Chúa, chúng con đã tin vào những gì Ngài mặc khải và chúng con đã đi theo Sứ giả, vì vậy hãy ghi chúng con làm nhân chứng.", "Vì sự kiên định trong đức tin và đi theo Sứ giả.", "Dua của các môn đệ của Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua của Ibrahim (AS) — Đừng làm tôi xấu hổ", "Và đừng làm nhục tôi vào Ngày họ sống lại.", "Để được an toàn khỏi bị sỉ nhục vào Ngày Phục Sinh.", "Dua của Ibrahim (AS) cho Đời Sau."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar - Vì bạn tôi đã nhịn ăn", "Ôi Allah, vì Ngài, tôi đã nhịn ăn và với sự cung cấp của Ngài, tôi ăn chay.", "Khi nhịn ăn (iftar dua nổi tiếng).", "Nhà tiên tri ﷺ đã nói điều này tại iftar. Đó là một lời kể âm thầm được củng cố bởi những lời kể khác; đọc nó tại iftar là thói quen của Hanafis và đa số."),
        "dua_iftar_ibn_umar" to DuaText("Iftar - Bởi lòng thương xót bao la của bạn, hãy tha thứ cho tôi", "Ôi Allah, tôi cầu xin Ngài bởi lòng thương xót của Ngài, bao gồm tất cả mọi thứ, hãy tha thứ cho tôi.", "Tại iftar — Abdullah ibn Amr (RA) đã thực hiện điều này; dua của một người ăn chay tại iftar không bị từ chối.", "Hadith: dua của người ăn chay vào thời điểm iftar không bị từ chối."),
        "dua_inni_saim" to DuaText("Khi bị khiêu khích khi đang nhịn ăn", "Tôi đang nhịn ăn, tôi đang nhịn ăn.", "Khi ai đó xúc phạm bạn hoặc cãi vã với bạn trong lúc nhịn ăn.", "Nhà tiên tri ﷺ đã nói: ăn chay là một lá chắn, vì vậy người ăn chay không được nói năng tục tĩu hoặc hành động thiếu hiểu biết - nếu có ai cãi vã thì hãy nói điều này hai lần."),
        "dua_eid_takbeer" to DuaText("Takbeer trên đường đến lễ Eid", "Allah là Đấng Vĩ đại nhất, Allah là Đấng Vĩ đại nhất, không có vị thần nào ngoài Allah, và Allah là Đấng Vĩ đại nhất, Allah là Đấng Vĩ đại nhất, và mọi lời khen ngợi đều dành cho Allah.", "Từ đêm ngắm trăng cho đến lễ cầu nguyện Eid al-Fitr, đặc biệt là trên đường đến địa điểm Eid.", "Lệnh trong Kinh Qur'an: 'để bạn hoàn thành việc đếm và công bố sự vĩ đại của Allah' (al-Baqarah 2:185). Ibn Mas'ud (RA) đã nói điều này takbir."),
        "dua_ahsin_aqibatana" to DuaText("Làm cho mục đích của chúng ta trở nên tốt đẹp trong mọi vấn đề", "Ôi Allah, xin hãy giúp chúng tôi đạt được kết quả tốt đẹp trong mọi công việc và bảo vệ chúng tôi khỏi sự ô nhục ở đời này và sự trừng phạt ở Đời sau.", "Để có kết quả tốt đẹp trong mọi vấn đề.", "Bất cứ ai thực hiện dua này và chết trước khi bị xét xử sẽ chết (an toàn khỏi bị xét xử)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Tôi yêu cầu tiền thưởng và lòng thương xót của bạn", "Lạy Allah, con xin Ngài ban ân huệ và lòng thương xót của Ngài vì không ai sở hữu chúng ngoại trừ Ngài.", "Khi yêu cầu cung cấp và thương xót.", "Khách đến Tiên tri ﷺ khi chưa có đồ ăn; anh ấy đã làm món dua này và sau đó một món quà đã đến."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Những lời dạy cho một Bedouin", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Allah là Đấng vĩ đại nhất; lời khen ngợi dồi dào dành cho Allah; vinh quang thay Allah, Chúa tể của các thế giới; và không có sức mạnh hay quyền lực nào ngoại trừ Allah, Đấng Toàn năng, Đấng Thông thái.", "Một cụm từ đầy đủ về dhikr và dua — được dạy cho người Bedouin.", "Sau đó, anh ta được dạy nói 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Tha thứ cho những gì tôi đã gửi trước và sau", "Ôi Allah, hãy tha thứ cho tôi những tội lỗi mà tôi đã phạm trước và sau, những gì tôi đã làm trong bí mật và những gì tôi đã làm một cách công khai, những hành vi thái quá của tôi và những gì Ngài biết rõ hơn tôi. Bạn là Người đưa tới và là Người lùi lại; không có thần nào ngoại trừ Bạn.", "Sau tashahhud và salawat, trước salam.", "Nhà tiên tri ﷺ đã đọc điều này vào cuối lời cầu nguyện, giữa tashahhud và salam."),
        "dua_jiddi_wa_hazli" to DuaText("Tha thứ cho sự nghiêm túc và trò đùa của tôi", "Ôi Allah, hãy tha thứ cho tôi những tội lỗi mà tôi đã phạm một cách nghiêm túc và đùa giỡn, do nhầm lẫn và cố ý - và tất cả những tội lỗi đó đều ở trong tôi.", "Sự tha thứ cho mọi loại tội lỗi, đã biết và chưa biết.", "Một bản tóm tắt toàn diện về Nhà tiên tri ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Sau Ruku - Khen ngợi tràn ngập thiên đường", "Lạy Chúa, mọi lời ca ngợi đều thuộc về Ngài, lấp đầy các tầng trời, lấp đầy trái đất và lấp đầy bất cứ điều gì khác mà Ngài muốn sau đó.", "Sau khi trỗi dậy từ ruku, cùng với 'Rabbana lakal-hamd'.", "Nhà tiên tri ﷺ đã nói điều này khi trỗi dậy từ ruku."),
        "dua_istiftah_kabira" to DuaText("Allah là vĩ đại nhất, được ca ngợi rất nhiều", "Allah là Đấng vĩ đại nhất; lời khen ngợi dồi dào dành cho Allah; và vinh quang thuộc về Allah vào buổi sáng và buổi tối.", "Khi bắt đầu lời cầu nguyện (một hình thức khen ngợi mở đầu).", "Nhà tiên tri ﷺ đã nói: cánh cổng thiên đường đã mở ra cho nó."),
        "dua_q_ashku_bathhi" to DuaText("Dua của Yaqub (AS) - Tôi chỉ phàn nàn với Allah", "Tôi chỉ phàn nàn về nỗi thống khổ và đau buồn của mình với Allah.", "Trong nỗi đau buồn sâu sắc và sự chia ly.", "Ya'qub (AS) đã nói điều này khi chia tay Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah là người bảo vệ tốt nhất", "Allah là Đấng Bảo vệ tốt nhất và Ngài là Đấng Rất mực Khoan dung đối với những người có lòng nhân hậu.", "Khi đưa trẻ em hoặc người thân đi du lịch.", "Ya'qub (AS) đã nói điều này khi giao con trai mình cho Allah."),
        "dua_q_aqraba_rashada" to DuaText("Xin Chúa hướng dẫn tôi đến gần hơn với lẽ phải", "Có lẽ Chúa của tôi sẽ hướng dẫn tôi đến điều gần hơn thế này với cách cư xử đúng đắn.", "Khi tìm kiếm một cách tốt hơn trong một số vấn đề.", "Nhà tiên tri ﷺ được yêu cầu nói điều này khi quên."),
        "dua_q_sawa_as_sabil" to DuaText("Dua of Musa (AS) - Hướng dẫn tôi con đường đúng đắn", "Có lẽ Chúa sẽ hướng dẫn tôi con đường đúng đắn.", "Khi bắt đầu một hành trình mới hoặc một con đường xa lạ.", "Musa (AS) nói điều này khi quay về phía Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Đừng đặt tôi vào số những kẻ làm điều sai trái", "Lạy Chúa, xin đừng đặt con vào số những người làm điều sai trái.", "Một dua yêu cầu Allah giữ một người tránh xa những người làm sai.", "Một dua yêu cầu Allah giữ một người tránh xa những người làm sai."),
        "dua_q_do_not_make_us_trial" to DuaText("Đừng bắt chúng tôi phải thử thách", "Lạy Chúa, xin đừng biến chúng con thành thử thách cho những kẻ không có đức tin, và xin hãy tha thứ cho chúng con, Chúa của chúng con. Quả thật, Ngài là Đấng Toàn Năng, Đấng Thông Thái.", "Dua của Ibrahim (AS) và những người bạn đồng hành của anh ấy.", "Dua của Ibrahim (AS) và những người bạn đồng hành của anh ấy."),
        "dua_morning_witness" to DuaText("Buổi sáng làm chứng cho Tawhid", "Ôi Allah, tôi đã bước vào buổi sáng kêu gọi Ngài, những người mang ngai vàng của Ngài, các thiên thần của Ngài và tất cả sự sáng tạo của Ngài để làm chứng rằng Ngài là Allah, không có vị thần nào ngoại trừ Ngài, một mình, không có đối tác và rằng Muhammad ﷺ là người hầu và Sứ giả của Ngài.", "Lời tường thuật đề cập đến việc nói điều đó bốn lần vào buổi sáng.", "Lời tường thuật đề cập đến việc nói điều đó bốn lần vào buổi sáng."),
    )
}
